import math
    import random
    import time

    LANGUAGE_WRAPPER = 'For each real x in [0,1), define f(x) = sum_{n=1}^∞ {base}^{-n} over those n for which floor(n x + {offset_num}/{offset_den}) modulo {modulus} lies in the residue set [{allowed_residues}]. Let L_max be the largest real number such that f(x) ≥ L for all x ∈ [0,1). Determine the largest integer strictly less than {scale} · L_max.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Randomly generate a harder modular-offset geometric family instance.
tries = 0
while True:
    tries += 1
    m = rng.randint(3, 7)  # modulus ≥ 3
    b = rng.randint(2, 4)  # base 2..4
    q = rng.randint(3, 9)  # offset denominator
    p = rng.randint(1, q - 1)  # offset numerator (0 < p < q)
    # Choose a nontrivial residue subset size
    s_min = max(1, m // 2)
    s = rng.randint(s_min, m - 1)
    residues = sorted(rng.sample(range(m), s))
    scale = rng.choice([800, 1000, 1200, 1500, 2000])
    # Ensure tail < 1/scale; pick N target larger for difficulty
    N_min = 1
    while 1 / (b**N_min * (b - 1)) >= 1 / scale:
        N_min += 1
        if N_min > 60:
            break
    if N_min > 60:
        continue
    # Choose a larger N to increase number of breakpoints and difficulty
    N_target = max(N_min, 15)
    N_target = min(40, N_target + rng.randint(0, 10))
    # Build breakpoint set to check complexity (not stored in assignment)
    from math import gcd
    def add_rational(storage, num, den):
        g = gcd(num, den)
        storage.add((num // g, den // g))
    points = set()
    add_rational(points, 0, 1)
    add_rational(points, 1, 1)
    for n in range(1, N_target + 1):
        for k in range(1, n + 1):
            num = k * q - p
            den = n * q
            if 0 < num < den:
                add_rational(points, num, den)
    # Enforce nontrivial number of intervals for difficulty
    if len(points) < 50 and tries < 10:
        continue
    return {
        'modulus': m,
        'base': b,
        'offset_num': p,
        'offset_den': q,
        'allowed_residues': residues,
        'scale': scale
    }

    def verifier(assign):
# Validate input and compute the exact floor(scale * L_max) via rational partitioning and tail domination.
m = assign.get('modulus'); b = assign.get('base')
p = assign.get('offset_num'); q = assign.get('offset_den')
residues = assign.get('allowed_residues'); scale = assign.get('scale')
# Basic validation
if not isinstance(m, int) or m < 3:
    return False, None  # invalid modulus
if not isinstance(b, int) or b < 2:
    return False, None  # invalid base
if not isinstance(scale, int) or scale <= 0:
    return False, None  # invalid scale
if not isinstance(p, int) or not isinstance(q, int) or q <= 1 or not (1 <= p < q):
    return False, None  # invalid offset
if not isinstance(residues, (list, tuple)):
    return False, None  # invalid residues container
R = set()
for r in residues:
    if not isinstance(r, int):
        return False, None  # invalid residue type
    if r < 0 or r >= m:
        return False, None  # residue out of range
    R.add(r)
if len(R) == 0 or len(R) == m:
    return False, None  # trivial function (all or none)
# Choose N so that tail t_N < 1/scale
# t_N = 1/(b^N (b-1)) < 1/scale  <=> b^N (b-1) > scale
N = 1
while (b**N) * (b - 1) <= scale:
    N += 1
    if N > 80:
        return False, None  # unreasonable
# Build the union of breakpoints: x = (k - p/q)/n for k=1..n
from math import gcd
def reduce_pair(num, den):
    g = gcd(num, den)
    return (num // g, den // g)
points_set = set()
points_set.add((0, 1))
points_set.add((1, 1))
for n in range(1, N + 1):
    for k in range(1, n + 1):
        num = k * q - p
        den = n * q
        if 0 < num < den:
            points_set.add(reduce_pair(num, den))
points_sorted = sorted(points_set, key=lambda frac: frac[0] / frac[1])
# Difficulty enforcement: ensure enough intervals and N not too small
if N < 10 or len(points_sorted) < 50:
    return False, None
# Evaluate partial sum f_N at midpoints of each interval exactly using Fraction arithmetic
from fractions import Fraction
weights = [Fraction(1, b**n) for n in range(1, N + 1)]
min_val = None
for i in range(len(points_sorted) - 1):
    n1, d1 = points_sorted[i]
    n2, d2 = points_sorted[i + 1]
    mid_num = n1 * d2 + n2 * d1
    mid_den = 2 * d1 * d2
    g = gcd(mid_num, mid_den)
    mid_num //= g
    mid_den //= g
    # Evaluate f_N at x = mid_num / mid_den
    accum = Fraction(0, 1)
    for idx, n in enumerate(range(1, N + 1)):
        # floor(n*x + p/q) with exact rationals
        num = n * mid_num * q + p * mid_den
        den = mid_den * q
        floor_val = num // den
        if (floor_val % m) in R:
            accum += weights[idx]
    if (min_val is None) or (accum < min_val):
        min_val = accum
# With t_N < 1/scale, floor(scale * L_max) = floor(scale * min_x f_N(x))
ans = (scale * min_val.numerator) // min_val.denominator
return True, int(ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

